INSERT INTO public.questions (materia, topico, enunciado, alternativas, correta, explicacao) VALUES
('Língua Portuguesa','Crase','O delegado dirigiu-se ___ delegacia central e permaneceu ___ espera do laudo pericial. As lacunas ficam corretamente preenchidas por','["à ... à","a ... a","à ... a","a ... à","às ... às"]',0,'Quem se dirige, dirige-se a algum lugar: a + a delegacia = à. A locução feminina à espera de também recebe crase.'),
('Língua Portuguesa','Concordância verbal','Na seccional, ___ várias ocorrências registradas naquela noite e ___ diligências urgentes. Preenchem corretamente as lacunas','["havia ... eram","haviam ... era","havia ... era","haviam ... eram","fazia ... eram"]',0,'O verbo haver, no sentido de existir, é impessoal e fica no singular; o segundo verbo concorda com diligências.'),
('Língua Portuguesa','Regência','O perito procedeu ___ exame das lesões e comunicou o resultado ___ autoridade policial.','["ao ... à","a ... a","à ... à","ao ... a","à ... a"]',0,'Proceder exige preposição a (procedeu ao exame); comunicar algo a alguém (à autoridade).'),
('Língua Portuguesa','Pontuação','Está corretamente pontuada a frase:','["O escrivão, lavrou o auto imediatamente.","O delegado, determinou, a perícia.","Os policiais, que chegaram tarde, foram substituídos.","Concluído o laudo, o inquérito, foi remetido.","A autoridade, ouviu a vítima."]',2,'A oração explicativa entre vírgulas está corretamente isolada; nos demais casos a vírgula separa sujeito de verbo ou verbo de objeto.'),
('Língua Portuguesa','Acentuação','Todas as palavras estão acentuadas por serem proparoxítonas em:','["médico, último, pássaro","análise, saída, saúde","ocorrência, história, possível","também, você, até","fácil, difícil, útil"]',0,'Proparoxítonas são todas acentuadas; as demais alternativas trazem paroxítonas ou oxítonas.'),
('Língua Portuguesa','Conectivos','O laudo pericial foi conclusivo; ___, a autoridade policial determinou o indiciamento. O conectivo que expressa conclusão é','["portanto","contudo","embora","ou seja","isto é"]',0,'Portanto introduz conclusão; contudo é oposição, embora é concessão e ou seja/isto é explicam.'),
('Língua Portuguesa','Colocação pronominal','A colocação pronominal está correta em:','["Não me foi informado o prazo.","Não foi me informado o prazo.","Me foi informado o prazo.","Informado me foi o prazo.","Não informado me foi o prazo."]',0,'Palavra de sentido negativo atrai o pronome para antes do verbo; não se inicia período com pronome oblíquo.'),
('Língua Portuguesa','Paronímia','O laudo foi ___ para sanar erro material e, na sequência, ___ pelo chefe da perícia.','["retificado ... ratificado","ratificado ... retificado","retificado ... retificado","ratificado ... ratificado","ratifado ... retificado"]',0,'Retificar significa corrigir; ratificar significa confirmar.'),
('Língua Portuguesa','Interpretação de texto','Leia: a investigação moderna exige do policial não apenas domínio técnico, mas também senso crítico, pois o excesso de dados sem leitura qualificada produz conclusões frágeis. A ideia central do texto é que','["o volume de dados, por si só, garante conclusões seguras","o senso crítico é dispensável diante do domínio técnico","a qualidade da leitura dos dados é indispensável à investigação","a investigação moderna prescinde de conhecimento técnico","o excesso de informações elimina a necessidade de análise"]',2,'O texto valoriza a leitura qualificada dos dados, e não o acúmulo de informações.'),
('Língua Portuguesa','Reescritura','Mantém o sentido e a correção gramatical de a autoridade policial lavrou o auto de prisão a frase:','["O auto de prisão foi lavrado pela autoridade policial.","O auto de prisão lavrou-se a autoridade policial.","Foi lavrado o auto de prisão a autoridade policial.","O auto de prisão foi lavrado a autoridade policial.","Lavrou-se pela autoridade policial o auto de prisão."]',0,'A passiva analítica exige agente introduzido pela preposição por (pela autoridade).'),
('Raciocínio Lógico','Lógica de argumentação','A negação de todo delegado é bacharel em Direito é','["algum delegado não é bacharel em Direito","nenhum delegado é bacharel em Direito","todo delegado não é bacharel em Direito","algum delegado é bacharel em Direito","nenhum bacharel é delegado"]',0,'A negação de todo A é B é algum A não é B.'),
('Raciocínio Lógico','Equivalências','A proposição se o conduzido foi flagrado, então é autuado em flagrante é equivalente a','["se não é autuado em flagrante, então não foi flagrado","se é autuado em flagrante, então foi flagrado","se não foi flagrado, então não é autuado em flagrante","o conduzido foi flagrado e não é autuado","o conduzido não foi flagrado ou não é autuado"]',0,'A contrapositiva inverte e nega as duas partes: não q então não p.'),
('Raciocínio Lógico','Negação de proposições','A negação de se a diligência foi cumprida, então o inquérito foi concluído é','["a diligência foi cumprida e o inquérito não foi concluído","a diligência não foi cumprida e o inquérito não foi concluído","se o inquérito não foi concluído, a diligência não foi cumprida","a diligência foi cumprida ou o inquérito não foi concluído","a diligência não foi cumprida ou o inquérito foi concluído"]',0,'A condicional só é falsa com antecedente verdadeiro e consequente falso; sua negação é uma conjunção.'),
('Raciocínio Lógico','Sequências','Na sequência (2, 6, 12, 20, 30, ...), o próximo termo é','["42","40","36","44","38"]',0,'As diferenças crescem de 2 em 2: 4, 6, 8, 10, 12; logo 30 + 12 = 42.'),
('Raciocínio Lógico','Porcentagem','Uma seccional registrou 250 ocorrências em um mês. Se 40% foram furtos e, desses, 25% foram esclarecidos, o número de furtos esclarecidos foi','["25","100","10","40","62"]',0,'250 x 0,40 = 100 furtos; 100 x 0,25 = 25 esclarecidos.'),
('Raciocínio Lógico','Conjuntos','Em uma turma de 60 candidatos, 35 estudaram Língua Portuguesa, 28 estudaram Direito Penal e 12 estudaram as duas matérias. Quantos não estudaram nenhuma das duas?','["9","15","21","12","51"]',0,'União: 35 + 28 - 12 = 51; logo 60 - 51 = 9.'),
('Raciocínio Lógico','Probabilidade','Em uma urna há 3 fichas azuis e 5 vermelhas. Retirando-se uma ficha ao acaso, a probabilidade de ela ser azul é','["3/8","5/8","1/2","3/5","1/8"]',0,'São 3 casos favoráveis em 8 possíveis.'),
('Raciocínio Lógico','Análise combinatória','De 5 policiais, devem ser escolhidos 2 para uma mesma diligência, sem ordem definida. O número de escolhas possíveis é','["10","20","15","7","25"]',0,'Combinação simples: 5 x 4 / 2 = 10.')
